    (23, 6, "አሮንም ወደ ቤተ መቅደስ ሊገበ በአግዚጾብሔር ፊት በሚሠዋበት ጊዜ በሚሰማ ቃል ያድርግ ፡ ሲወጣም (እን ዳይቀሠፍ) እንዲሁ ያድርግ።"),
