        23,
        7,
        ") ወርቁን ከጸራ ወርቅ ለይተህ እንድ ቅጠል አሳስተህ ሥራ ፡ በላይዋም ላይ እንደ ማኅተም ቅርጽ (ራክ ወርቅ) ቅረጽበት ፡ በራስ ወርቁም ላይ (አህያ ሸራህያ አልኻዳይ) የሚበሉ ቃላት ቅረጽበት።",
