    (26, 8, '፩ ቁሮ፡ ፲፮" ት እግዚRብሔርቻ. ሙሴን እንዲህ ብሎ. ተናገረው ! (ከደብረ ሹና) ፈጥነህ PL) ሂድ = እህ ናቸው አሉ።'),
    (26, 9, "8 ነገ TE ፳ቿ F አንገተ ደንዳና ሕኽብ ነው 7) ሣሯ 8።"),
    (26, 10, "እሁንም ተቄጥቹ ላጥፋቸው ተወኝ ከዚሀ በሚበል y ና ብለህ) በራስህ የማልክኣቭው አገል ሊያጨጠፉቸወ።"),
    (26, 11, "(ወገኖቹ ኋስራኤልን) በክፉ ነገር አወጣቸው | አንዳይሉ የተቆጣህበቸውን ቁጣ ኣብርድላቸው . የወገኖች ;[ ሀንም በደል ቅር በይ ሁን (ይቅር በል)።"),
    (
        26,
        12,
        ". . wo ክነኝንን ለዘለዓለሙ ሊንዪትና ሊወርቡዋች ዘራች | ' ሁን ጃንድ ብዙ እን ድ ሰማይ. ከዋክብት አበዛዋለሁ ይህን, (Nያውዩ , አማንየ, ) ህ አብርሃም ይስ ሐቅ ያፅቆብን አስብ።",
    ),
    (
        26,
        13,
        "ዕብ፡. {8 TE = አግዚ አዳፌርም፡ በሕዝፍ ላይ አደርጋታለሁ ብሎ የተ\" F eg Hk | ሕዝቡም ሙቤ ከደብረ ሲና መውረዱን. እንዶ ዛዘዝገየበ አሮንም በነኝታ ው ማለኝ ተነሥቶ መሠዋዕቂን Ae ) ተደፉ . መሥዋዕ ሊበሉ, ክግብጽ አቲ ያወጣኻቸው መገኖ ችህ በድለዉኛልና hay. ኽ እሄ ከዘዝኋቸው ሕግ ሥርዓት ወጥተው በደሉ tA b ንም ምስል ሠርተው አቁመው ስገጽለት ፡ መሥዋዕቱንም. ም ሠጳት ፣ ክሸራኤል ከግብጽ ያወጡህ አማልክቶችህም ፤ ግዚአብሔር ሙሌን ይህን ሕዝብ አየሁት ክሆም |. ሙሌም fፈጣéው '&£ት ቕሞ ጽNE (A=RዜE Vግ ie =, ብጽ ጸንር በጽሩ ኃይል በል ልና በታላቅ ሥልጣን, ያወ, . ጣኻቸው ወንኖችህኝ ለምን ተቋጥተዕ ታጠፋቸዋለህ አለ የዳብጽ ስዎች በተ ራው ሊገድላቸው hug: Sለም ክርስቲያን ሃይማኖችና ሥርዓ ዕራፍ RE = ፍናገራትን የክፉይቱን ነገር ይቅር ክለ (ተወ)።",
    ),
    (
        26,
        14,
        "ሙሴም ተመልሰ ከደብረ ሏና ወረደ ፡ ያሠርቱ ቃላት የተጻፉበቸው ሁስቱም ጽላቶች በክጁ ተይዘው ነበር ጽላ ቹም የዕንኮ' ናቸው እነዚህም በጐናቸው በሁለት ወገን, ግራና ቁኝ ፀሠርቱ ቃላት የተጻፉብቸው ናቸው።",
    ),
    (26, 15, "አሠራራቸው የጌታ ሥራ ነው ፡ ክጻጻፋቸውም የአኝ ዚአብፌጨር አፍ ነው ፡ (ወፀወሠርቱ ቃላትም) በሁጸቱ ጽላ ቶች ላይ ተቀርጾወል ፡ (ተጽፈዋል)።"),
    (
        26,
        16,
        "| ኢያሱም የሕዝቡን ጩኸት ሰምቶ መሌሴን ብቦተ ማው የሰልፍ ድምፅ አለ (አሰማለሁ) አለው = ሙዜም ይህ የምትስማው ለሰልፍ የሚበረታቱ የአር በኞች ድምፅ አይዶለም የተሸናፊዎች ድምፅም አይዴለም ድምፀ ፋሕሉ ለወይን) እስራኤል ያልረፈላ ጐሽ ጠጅ ጠጥ ተው የሆነውንና ያልሆነውን ይስፈልሩሉ እሰማለሁ አንጂ አለው።",
    ),
    (26, 17, "መሬም ወደ ከተማው በቀረሽ ጊዚ ጥጃውንና ዘራኑን አይቶ ተፍጣ ፡ አሊህ ሁለቱን ጽላቶች ከአጆቹ ጥሎ ከተ ራራው በታች ሰበራቸው።"),
    (26, 18, "የሠሩትንም ጣፆጾት (ጥጃ! ወስዶ በአፅት አቃጠለው t ረጭቶም አደቂቀው ፡ ከፈሳሽ ውኃም በጥብጦ ልኣአስራ ኤል ልጀች ያነኑን አጠጣቸው።"),
    (26, 19, 'ሙሴም አሮንን በነሱ ላይ ታላቅ ኃጢአት ይታመጣበ " ቸው ይህን ሕዝብ ለምን አንዲበድል አደረግኸው አለው።'),
    (
        26,
        20,
        "‘አሮንም ሙሴን እንዲህ አለው ! አቤቱ በኔ ላይ አት በቋጭብኝ የኒህ ወገኖች ሥራቸውን አንተው ቀሉ ታው ቀፍላህ = | ከግብጽ አገር ያወጣን ስው ሙሴ ምን አንደ ሆነ ጸና ውቀምና በፊት በፊታችን የሚሄኔዱልን ጠላቶቻችንን የሚ ያጠፉልን ጾማልክት ሥራልን ሉኝ።",
    ),
    (26, 21, "አኔም ከናንተ ወርቅ ያለው አምጡ አልኳቸው አነ ሱም አምጥተው ሰጡኝ እኔም አስት አስነድጅ በዚያ ላይ ጣልሁት ፡ ይህም ጥጃ ወጣ።"),
    (26, 22, "ሙሴም ኦሮን ክስወንጅሏቸዋልና ለጠላቶቻቸውም | መዘበበቻ ሁነዋልና ሕዝቡ እንደ ወነጅሉ፡ ባየ ጊዜ ኣግ ዚአብሔር የወደደው የመረጠው ሰው ወደኔ ይምጣ አለ።"),
    (
        26,
        23,
        "በከተማው መክከል ቆሞ እንዲህ የሌዊም ጆች ወድጡ ተሰበሰቡ --- የአስራኤል ፈጣሪ አግዚአብሔር አንዱም አንዱም ሰይፉን በብብቱ ይሸክም ፡ (በወገቡ ይታጠቅ) ከበርም ኣስ ከ ክተማው በር ሂዳችሁ ክበቡ ፡ ኣንዱም አንዱም. ወንድ ሙን ይግደል ፡ አንዱም አንዱም . በልንጀራውን ይግዴል አንዱም አንዱም ጎረቤቱን ይግዴለው ብሏል እለ።",
    ),
    (26, 24, "የሴዊም ልጆች ሙሴ እንዳላቸው አደረጉ ፡ ያን ጊዚ ም ከሕዝቡ ሦስት ሺህ ሰው ሞተ።"),
    (
        26,
        25,
        "ቆሮ መ-ሴም የአግዚአብሔር በረከቱ ትሰጣችሁ ህንድ በአ | ጀጆቻችሁ ከናንተ አንዱም ጸንዱ ሓጅን ወንድሙን በመግ ደላችትሁ ዛሬ አግዚአብሔርን ዶስ አሰኛችሁት አላቸው።",
    ),
    (
        26,
        26,
        "በበነጋው አንዲሀ ሆነ ሙሴ ወገኖቹን ታላቅ በደል በድላችትኋል ፡ አሁንም አማልጅ ቃጢይታ ችሁን አስተመር ክርስቲያን ሃይማኖትና ሥመርዓች ዘር P23 ይላችሁ ዘንድ ወደ እግዚእብሔር (ወደ ደብረ ሊና) እወ. - ጣለሁ አላቸው።",
    ),
    (
        26,
        27,
        "መ-ሴም ወደ እግዚአብሔር ተመል አቤቱ እለምን ብለሁ እነሆ እኒሀ ሕዝብ ታላቅ በድል በደሉ የወርቅ አማ ልክትን ለራሳቸው ሠሩ አለ = '' እሁንም ይህን ጽኑ በጄል (በቸርነትህ) ይቅር ብትላ ቸው ይቅር በላቸው ያለዚያ ግን ከጻፍከኝ መጽሐፍህ እሄን ዶምስሰኝ = መዝ፡ ጃክ ፳ሯ፡ ሮሜ ከ {= እግዚአብሔርም ሙሱን እንዲህ ለው ፣ በፊቱ የበድ ለኝን ይሀን ወገን ከመጽሐፌ አውጥቼ አዶመስበዋለሁ = አለው = ) ' አሁንም ሂድ እነዚህን ወገኖች መርተህ ወዳልኩህ ' ቦታ ውሰዳቸው ፡ እነሆም መልአኬ በፊትህ ይሄዳል ነገር ; ግን (በመኝት) በጐበኘዳቸው ቀን ኃጢአታቸውን በራሳ ' ቸው ላይ አመጣባቸዋለሁ = ዘገሩ፡ ፪ ፲፮።",
    ),
    (26, 28, "ዘሌዋ፡ ር ፳፡ ሕዝ ፲መ 8 አሮን ሠርቶ የሰጣቸውን ላም አምላክ አድርገው ስላመ ' ለኩ እግዚአብሔር ከሕዝቡ ወገን ብዙ ሰው ገዴለ (አጠፋ)።"),
    (
        26,
        29,
        "እግዚአብር ሙሴን እንዲህ አለው! ie አሰጣታለሁ ብዬ ለአብርሃም ለይስሐቅ ለያፅቶብ ወዶ ማል ላቸው (ወደ ከነዓን) ከግብጽ አገር ከወጣኻቸው ወገና ችህ ጋር አንተ ከህ አገር ወጥተህ ሂድ።",
    ),
    (
        26,
        30,
        "መልእክተኛዬንም ክንተ አስቀድሜ ወደ ከነኝን እሰደ ዋለሁ ፡ እሱም ሂዶ ከናኔዎንን አሞሬዎንን' ኬጤዎንን ፌርዚዜዎንን ጌርጌሴዎንን ኤዌዎንና ኢያቡሌዎንን (ከከነ ዓን አገር) ያወጣቸዋል (ያጠራቸዋል)።",
    ),
    (
        26,
        31,
        "አሱም እየመራ ወስዶ ወተትንና ማርን ወደም ታፈ ሰው ምድር አላገባህም ፡ አኔ ግን የበደሉኝን በድል (አስቤ) በጐዳና እንዳላጠፋቸው ክሣደ ልቡናቸውን ከስላጺኑ ወገና ችህ ክፋት ካንተ ጋር አብሬህ ልወጣም አለው።",
    ),
    (26, 32, "ሕዝቡም ይሀን ክፉ ቃል በሰሙ ጊዜ ጽኑ ልቅ አለቀሱ •።"),
    (
        26,
        33,
        "እግዚአብሔር ሙሴን የአስራኤል ን ልጆች እንዲህ በላቸው አክለው እናንተስ ክሣድ ልቡናውን ያጻኝ መገኖች ናችሁ ፡ ከዚህ ቀድሞ ክመጣሁት መቅሠፍት ሌላ መቅሠ ፍት አምጥቼ እንዳላጠፋችትሁ. ዕወቁ ተጠንቀቁ ፣ አሁ ንም ለጣዖቱ በዓል ከብራችሁበት አጊጻችሁበት የዋላች ሁበትን ልብስ ከናንተ አስወግዱ ይህን ያደረጋችሁ እንደሆነ የማደርግላችሁን አያችኋለሁ።",
    ),
    (26, 34, "| የእስራኤልም ልጆች ለጣዖቱ በኝል (የጌጹበት) ልብ - ሳቸውንና ጌጻቸውን በከሬብ ተራራ አስወገዱ ፣፡ (ጸራቁ)።"),
    (
        26,
        35,
        "' ሙሴም ድንኳኑ ይዘ ከከተማ በአፍኣ ራቅ አድርጎ ተከላት ይህችውም ደብተራ ኦሪት ተባለች ያን ጊዜ እግ ዚአብሔርን በሕግ በአምልኮት የሚሻው ሰው ሁሉ ከከ . ተማ በኣፍኣ ወደ ተተከለች ወድዚያች ድንኳን EER ነበር = ዘ ፲፮ ፳ቛ፮።",
    ),
    (26, 36, "ሙሴ ከከተማ በአፍኣ ራቅ ብላ ወደ ተተከለች ድን ኳን ሊገባ በሄድ ጊዜ ቋዝብ ሆሉ ይቆም ነበር እስኪገበም ክርስቲያን ሃይማኖችና ሥርዓተ።"),
    (26, 37, "L |. ማለሁ ጸለው።"),
    (27, 1, "ድረስ በሚኔድበት ጊዜ አንዱም አንዱ በድንኳኑ ደጃፍ ሁኖ መ-ሴን ያየው ነበር።"),
    (27, 2, '" ሙሴም ወደ ድንኳነ ከገበ በኋላ ዓም ይዬ ደመና ወርዶ |. በድንኳኑ ደጃፍ ይቆም ነበር ፡ እግዚአብሔርም ሙሴን ቋል ለቃል ይነጋገረው ነበር።'),
    (27, 3, "| F3ንም ምደ ድመኛ ከድንኳኑ ላይ ዥም PT i ) ያየው ነበር።"),
    (27, 4, "እግዚአብሔርም ከሙሌ ጋር ቃል ሶቃል ይነጋገር ነበር, ሕዝቡም ሁሉ በየድንኳናቸው ቁመው (ለጌታ) ይስግዱ.ስት ነበር።"),
    (
        27,
        5,
        "አግዚአብሔርም ሙሌን ሰው ከወዳጅ ጋር አን ድሚነ ጋገር ፊት ለፊት ይነጋነረው ነስር ፡ (ክተነጋገረውም በኋላ) ወይ ከተማው ይመለስ ነበር ፡ አገልጋዩ የነዌ ዕጅ ሆጫፅ ግን ገና ሕፃን ነበርና ከከተማው .አይወጣም ንበር = ሙሴም እግዚአብሔርን አነሆ ይህነን ሕዝብ አንተ መርተህ ውስይው አልከኝ ፣ ነገር ግን ጸንተ ከኔ ጋር የም ትልከውን ስሙ አልነገርከኝም ፡ አንተ ከሁሉ ድይልጭቋ ዞን ተን ወደድኩህ ፡ በኔ ዘንድ በለሟልነትንኝ አገኘህ አልሾኝ በንተም ዘንድ በልሟልነትን ዘገኘሁ ፊትህን ገልጠህ ዶላ ሮኝ ፡ ለኔም ዛሬ በንተ ዘንድ በልሟልንትን ማግኘት ይሆነኝ ዘንድ ይህም ወገን በንተ ዘንድ የከበረ ወገን እንደሆነ 8 ውቅ ዘንድ ፊትህን አህ ዘንድ ገልጠህ አሳየኝ አለው = አግዚአብሔርም አኔ በፊትህ እቕዳላሁ ጸሳርፍህዕ ug! a8 B።",
    ),
    (
        27,
        6,
        "i ሙሴም እግዚአብሔርን እንዲህ አለው ክንተው ራሕ፱ . ' ከኛ ጋራ ክልሄድክ ከዚህ ቦታም ክላወጣሽን አንታ ከኛ ጋራ ብትሄጅ ነው ፡ አኛም በንተ ዛንድ በልሟልነትን ቁና ገኝ ነው እንጂ አኔም ሆን ወገና ችህ (አክራኤል) በንተ ዘንድ በለሟልነትን አንዳገኘሆ በምን ይታወቁ ፣ አለው።",
    ),
    (27, 7, "ንተ ክኛ ጋራ ከሄድክ ግን አኔም ወገኖችህ (አስራ ኤል) በዚህ ዓለም ላይ በሎ አሕዛብ ሁሉ ዘንድ ክንክብራ ፊኘ ክስው።"),
    (
        27,
        8,
        'እግዚአብሔርም ሙሌን አንዲህ እለው ፤ በሄ ዛንድ በለሟልነትን አግኝተ"ኻልና ከሁሉም ለይቼ ወድጅኻለሁና ያነን ያልከኝን ነገር እድርግልኻለሁ ክሰው = ሙሌጴም እግዚአብሔርን ጌትነት ክን (ገልጠህ) አሳየኝ አስው።',
    ),
    (
        27,
        9,
        "~~ እግዚአብሔር - mhን- -ኽንዲህ- ~ክስው እኔ በፊትህ ------ --.-- ----. የጌትነቴን ከም እየጠራሁ በፊትህ አልፋለሁ የምምሪረውን እምረዋለሁ ይቅር የምለውንም ይቅር እለዋለሁ።",
    ),
    (
        27,
        10,
        "= እግዚአብሔርም ሙሌን ፊቴን አይፉ የሚድን የለምና ፊቴንስ ማየት አትችልም አለው = አግዚአብሔር ሙሌን እንዲህ አሰው እነሆ በኔ ዛንድ በታ አለ ፡ የጌትነቲም ቃል ተነግሮ አኮስከ.ፈጸም ድረስ በአ “ለቱ ላይ ትቀመጣለክ።",
    ),
    (
        27,
        11,
        "በአለቱም ውስጥ አኖርኻለሁ ፡ የ፮ትነቴንም ነገር ተኝ ግሬ አስካልፍ ድረስ አጅን በላይህ አጋርዳለሁ (በሥልጣኔ እሠውርኻ ለሁ) x | | (ከጥሽው. ውስጥ ላለህ) እጁን ካንተ ላይ አነሣለሁ ያን ጊዜ ኣላዮን ታደለክ ፡ ፈቱን ግን አታየውም ዮሐ፡ ክ ፲ኛ።",
    ),
    (27, 12, "ክርስቲያን ሃይማኖትና ሥርዓች ፍ 8 = | Ezy።"),
    (
        27,
        13,
        "እግዚአብሔር ሙሴን እንዲህ አለው! እንደ ፊተኞቹ - ሁለት የአብነ በረድ ጽላቶችን ቀርጻህ ወደ . ደብረ ሊና ' ወደኔ ውጣ ፡ በሰበርክቸው በቀደሙት ሁለት ጽላቶች ተጽፎ የነበረውን ያን ዐሠርቱ ቃላትን በነዚያ ጽላቶች ላይ እጽፋለሁ።",
    ),
    (27, 14, "ዘዳግ, ፲ 8 ለነገም የተዘጋጀህ ሁን ነገ ይሀን ጊዚ ኣኔ ወዳለሁበት ወደ ደብረ ሲና ወጥተህ በተራራው ራስ ላይ ቁም።"),
    (
        27,
        15,
        "ክንተ ጋር የሚወጣ ሰው የለም (አይኑር) በተራራ ውም ዙርያ ሁሉ የሚኖር ሰው ጸይኑር ፡ (ክንኳን ለው) ላሞችና በጎች ስንኳ በተራራው አቅራዚያ ኣይሠማሩ አስው = ሙሴም እንደ ቀደሙት ሁለት የአብነ በረድ ጽላቶች ቀርጾ እነዚያን ሁለት የአብነ በረድ ጽላቶች በአጅ ይዞ አግዚአብሔር ኣንዳዘዘው ጧት. ie ስግስ ወድ ዴብረ ቧና ወጣ።",
    ),
    (27, 16, "እግዚአብሔር በደመና ወርድ በዚያ (በድብረ ሲና) is ih ገዥ የሚሆን ስሙንም እግዚአብሔር ብሎ ጠራ።"),
    (27, 17, "; ያን ፒዜ ጌታ አግዚአብሔር ስሜ “መቋቁሪ ፡ ይቅር ባይ ከመዓት የራቁ ፡ ምሕረቱ የበዛ እውነተኛ ነው አያለ በሙሴ ፊት ጸለፈ።"),
    (
        27,
        18,
        "ኢዬ 13: ሮሜ ዩ = (አውነትን) የሚጠብቃት እሱ ነው ፡ ለብዙስሰዎች ይቅ ርታን፡ ግፍን በደልን ኃጢአትን ከሰው የሚያርቅ እሱ ነው ፡ በደለኛውን ግን ከፍዳ አያነጻውም ፡ ያባቶችን ኃጢ ' ኣት በልጆች ' የልጆችንም ኃጢአት በልጅ ልጆች “ላይ እስከ ሦስት አስክ አራት ትውልድ ድረስ የሚያመጣ እሱ ነው።",
    ),
    (27, 19, "ሙሴም ይህን ሰምቶ ፈጥኖ ወደ ምድር ወድቁ ለእ ግዚአብሔር ሰገደ።"),
    (
        27,
        20,
        "ዜር፡ ቋ፪ ፲፳ = ሙሌ እግዚአብሔርን እንዲሀ አለው ፣ በፊትህ በለሟ ልነትን አግኝቼ እንደሆነ አንተ ጌታዬ ከኔ ጋር ሂድልኝ ይሀ ወገን ክሣደ ልቡናውን ያጸና ነውና ፡ አንተ ግን የዚ ሀ ቋኻብ በደሉን ኃጢአቱን ይቅር በለው ፡ (ድህን) ያደረ ግሀለት. አንደሆነ አኛም ላንተ እንሆናለን (እንገዛለን)።",
    ),
    (
        27,
        21,
        'እግዚአብሔርም ሙሴን እንዲህ አለው ፣ በወገኖችህ ሁሉ ፊት እነሆ ቃል ኪዳን አደርግልኻለሁ (ብርሃሄን በፊ ያውቅ በሕዝቡም በአሕዛበ-ም ዘንድ ተደርን የማያውቁ ታላቅና ድንቅ ተአምራቴን አድርግልኻለሁ ይህም እኔ የማ ደርግልህ ተአምራት ድንቅ ነውና አንተ ያለህበትም ሕዝ \' ብ፡ሁሉ (የሄን) የእግዚአብሔርን መሥራ ያያል =" ነገር ግን እንተ እኔ የማዝሀን ሁሉ ዕወቅ ፡ እነሆ "እኔ አሞሬዎንን ኬጤዎንን ፌርዚዎንን ጌርጌዜዎንን ኤዌዎን ንና ኢያቡሴዎንን ከፊታችሁ አውጥቼ አበዳቸዋለሁ።',
    ),
    (
        28,
        1,
        "እንግዲህም ወዲህ በናንተ ላይ ዕዳ በደል እንዳይሆን በችሁ ወፎ ምትገቡበት ወደዚያች አገር ከሞት ከቀሩ ሰ ዎች ጋራ እንዳት ማማል ራስህን ዕወቅ (ጠብቋ) - መሠውያዎቻቸውን አፍርሱ ምስሎ ቻቸውንም ስበሩ የሚያመልኩበቸው ዛፎቻቸውን ቍ.ረጡ ፡ (Sይን አጅ እግ ትህ እስልብኻለሁ) በዚህ ዓለም-ሁሉ እንደሱ ተደርጎ የማ -- -- - ክርስቲያን ሃይማኖችና መርዓት ፅራፍ 88 = f ር) የተቀረጸበቸው ጣፆቶቻቸውን በአሳት አቃጥሉ = የአግዚአብሔር ስሙ ቀናተኛ ስለሆነ አግዚአብሔርም - ስአምላክነቱ ቀናተኛ ነውና ዘሌላ አምላክ አት ስገዱ።",
    ),
    (
        28,
        2,
        "ክዐ፡ ጽደ፡ ኢላሓ፡ ኝ፮ IE s በዘያች ምድር ከሚኖሩ ሰዎች ጋራ አክ ትማማሉ ይሆናል ሰስኑ ለጣያቶቻቸውም ትሠዉላቸው ይሆናል፡ ወይም እኮ ለጣፆቱ በኃል ይጠሩክና ፲ዴህ ተረፈ ጣፆቱን ትበላ ይሆናል።",
    ),
    (
        28,
        3,
        "ሂደህም ሌቶች ልጆቻቸውን አጭተክ ለወንዶች ልጆ ችህ ሌቶች ልጆችህን ወስደህ ለወንድች ልጆቻቸው ታጋ በለህ ፡ ያገቡዋቸውም የአሕዛብ ሴቶች ጣቶቻቸውን ተከ ትለው እንዲሰስኑ ያዶርጓቸዋል ሴቶች ልጆችህም ጣያቶ ቻቸውን ተከትለው አንዲሰስኑ ያደርጓቸዋል (አንዳያደር ጓቸው ተጠን ቀቅ)።",
    ),
    (28, 4, "ተመትተው የተሠሩትን ጣያፆቶች ላንቱ አታድርግ ፡ (ሠርተህ አታምልክ)።"),
    (
        28,
        5,
        "ዛወ፡ ሸር iደ = ቁጣ የምት በሉበት የበዓሉን ሕግ ጠብቅ ፡ ከግብጽ አ ገር በሚያዝያ ወር ወጥተኻልና በሚያዝያ ወር በዛመኑ ሥርዳቱን ጠብቅ ብዬ አንዳዛዘዝኩህ ሰበት ቀን ቁጣ ብላ።",
    ),
    (28, 6, "መጀመሪያ የተወለደ ወንድ ወንዱ በዙር ልጅም ሓኔ ነው ፡ የላሙም የበጉም የአሀያውም በዙር የኔ ነው።"),
    (
        28,
        7,
        "የአህያውን በዙር ግን በበግ ለውጠው ፡ በበግ ክልለ ወጥከውም ሽጠህ ዋጋውን ስጥ ፡ የበዙር ልጅህንም ሁሉ ዋጋውን ሰጥተህ ተበዥተህ አስቀረው በፊቴም በዶ እጅ ህ አትታይ ፡ (መበእህን ይዘህ ግበ)።",
    ),
    (28, 8, "ከድስት *ን አረክ ቈፍር ፡ በሰበተኛው ቀን ግን ፅረ ፍ፡ ከመዝራትም ከማጨድም ዕረፍ።"),
