    (28, 39, "ለሚቃጠል መሥዋዕት የሚሆን መሠውያውን የናሱ ንም መከታ መሸከሚየዎቹን ዕቃዎቹን ሁሉ የመታጠቢ ያው ሰኑን ዳክውን ከነ መቀመጫው።"),
    (28, 40, "' ዩአዶበበዩን መጋረጃ ምዕስስዎቹን አግሮቹቸንም የአደ በዩን ደጃፍ መጋረጃ የድንኳን ክስማዎች የአዴበበዩን ክስ ማዎችና አውታሮቹንም።"),
    (28, 41, "በመቅደስ ውስጥ ለማገልገል በብልሃት የተሠፉም የክህትኑ የአሮን ልብዕችን በክህነት ለማገልገል የተቀደሱ የልጆቹንም ልብስች።"),
    (28, 42, "የአስራኤል ልጀች ማሣበሮችም ሁሉ ከሙሌ ፊት ወጡ።"),
    (28, 43, "አንዱ ክንዱም ልቡ ኣንዳሰበውና መንፈሱም አንደ ወደደው ለኮግዚአብሔር መባውን አመጣ ፡ ለመገናኛው ድንኳን ሥራ ሁሉ ለሚያስፈልገው ሁሉ ስመቅድስም ልብሶች ሁሉ።"),
    (29, 1, "ወንዶችም ከሌቶች ዘንድ ልቡናቸው ያሰበውን ማር ዳዎችን ንፎ መንዴልቶን (ሎቱቲዎች) ቀለበቶችን ድሪዎችን አምበሮችን የወርቅ ጌጦችንም ሁሉ አመጡ።"),
