    (
        29,
        4,
        "' - |; በኣጅዋ መ ፍተልን የምትችል ዜትም የሰማያዊወን--- - - -- | የሐምራዊውን የቀይና የብ“ጫውን ሐር ፈትል ክመጣች፣ ' (እንስጥ ብለውኝ) በልቡናቸው ያሰቡ ቤቶችም “ሁሉ ' አመውጡ፡ የፍየሉንም ጠጕር በብልህነት ብጥበብ ተሉት ... ኣለቁችም. የዕንቀኑ ደንጊያዎች (እብነ በረድ ሐኤፉ ድና ለደረት ኪስ የሚጎቡት ፈርጦችን።",
    ),
    (29, 5, "ek ፡ ለመብራት 'ዝይትን ለቅብቦት ሽቱን ለሚያጥኑት “ጣፋ | ጭ ዕጣንን አመጡ።"),
    (
        29,
        6,
        'rs " መወንዶችና.ሕቶች ሁሉ ልቡናቸው የፈቁቀደውንኛ አግ ዚአብሔር በሙሌ ቃል ያዛዛውን ሥራ ሁሉ ይሠኛ ዝንድ’ . . | የእስራኤል ል ጆች “ለአግዚአብሔር ስጦታን ክመጡ።',
    ),
    (
        29,
        7,
        "-. ' . ሙሴም የእስራኤልን ልጆች እነሆ እግዚአብር ክኛ ; , 1, ግጅ ይሁዳ የሆነውን የሕር የልጅ ልጅ የኡሪ ሓጅ ብስል. ክርስቲያን ሃይማኖትና ሥርዓት ፍ IY R IEE ኤልን በስሙ ጠራው Nites 8 ts መዋ RRBs ሪ በሥራ ሁሉ በጥበብም በማስተዋልም በዕውቀትም የአናዉዎች ሁሉ ለቃ ይሆን ዘንድ የእግዚአብሔርን መንፈስ ተመላ።",
    ),
    (29, 8, "ዘፀ፡ ዘኔ Es ፣ ሠራውን ሁሉ ይሠራ ዘኝዱ በወርቅ ዘብርና በናስም ይሠራ ዘንድ።"),
    (29, 9, "በፈርጥ የሚሆነውን የፀንቀ ድንጋይ ይቀርፅ ዘንድ ፅኘጨቱንም ይጠርብ ዘንድ በብልሃት የሚሠራውን ሥራ ሁሉ ይሠራ ዘንድና ያስተምርም ዘንድ።"),
    (29, 10, "<i; እርሱና የነገደ ዳን የሆነው የአክሴምክ ልጅ ኤልያ ብን የስተምሩ ዛንድ በልቡናቸው እሳደረበቸው።"),
    (
        29,
        11,
        "የመቅደስን ሥራ ሁሉ መሥራትን ይሠሩ ዘንድ በሰ ማያዊ ሐር በሐምራዊ ሐር ዕጽፍ ሁኖ በተፈተለ ቀይ ሐር በብጫው ሐር የሚሠራውን ሥራ ሁሉ ያውቁ ዘንድ ልዩ ልዩ 'የአጸጠራረብም ሥራ ሁሉ ይሠፉ ዘንድ ES ጥብኝ መላበቹቸው።",
    ),
    (
        29,
        12,
        "የሚፈለገውን ለመቅደስ ማገልገያ ሥራ እንዲሠሩ ጥበብና ዕውቀት የተሰጣቸው ቫበካልኤልና ኤልያብ የልብ ዕውቀት ያላቸውም ሁሉ አግዚጸብሔር በሙሴ ቃል ያዛ ዘውን ሁሉ ሠሩ።",
    ),
    (
        29,
        13,
        "ሙሴም በስእኤልና ኤልያብን እግዚጸብሔር በልበ ቸው ጥበብን ዕውቁትን የሰጣቸው ሁሉ ሥራውን ለመሥ ራት በልበ'ናቸው ፈቃድ የተነሣውትን ሁሉ ድውን ሠርተው ይፈጽሙ ዘንድ ጠራቸው '።",
    ),
    (29, 14, "የአስራኤል ልጆች ይሠሩ ዘንድ ለመቅደስ ሥራ ያመ ጡትን ስጦታ ሁሉ ከሙሴ ፊት ተቀበሉ ፡ እነሱም በፈቃ ዳቸው ያቀረቡትን ፅለት ፅላት ወደርሱ ያመጡ ነበር።"),
    (
        29,
        15,
        "የመቅደሱንም ሥራ የሚሠሩ ጠቢባን ሁሉ ጸንዱም አንዱም እንደየሥራው በመሥራት መጥተው ፡ ክግዚእ ብሔር ይደረግ ዘንድ ክዛዘው መሥራ እጅግ የበዛ ስጦ ሕዝቡ ዘመጡ ብላው ስሙሴ ነገሩት።",
    ),
    (29, 16, "ሙሴም ወንድም ሴት ለመቅደስ ስጦታ ከዚፀ የበለስ የሚያመጣ አይኑር’ ብሎ በሰፈሩ አዛዛ፡ (አወጀም)።"),
    (29, 17, "ሕዝም ሸጦታቻኘ ዘማቐደብ ተክለክለ ያመት ነገር - - - - -- ሥራን ለመፈጻም በቅቶ ተርፎአቸዋልና።"),
    (
        29,
        18,
        "በልበቸው ብልሃተኞች የሆኑ ሁሉ የድንኳፉን ሥራ ከተረተለ ከጥሩ በፍታ ከሰማያዊና ከሐምራዊ ሐር ከቀድ ግምጃም ዓሥር መጋረጃዎችን ሠሩ ከእነርሱም በላይ ብልህ “ሠፎተኛ በሚሠራው አሠራር gry አደረ ጉብቸው።",
    ),
    (29, 19, "ዘፀ፡ ጽ፪8፡ ምሳ 20: ያንዱም መጋረጃ ርዝመት ሃያ ስምንት ክንድ ፡ ወር ዱም አራት ክንድ ለክንዱ መጋረጃ ነው የመጋረኝዎ ቐም ሁሉ እንዲሁ በዚየው ልሽ ነው።"),
    (
        29,
        20,
        "አምስቱንም መጋረጃዎች አንዱን ከክንዱ ጋር እርስ በር ሰቸው አጋጠሙ፣ ደግሞም ምስቱ iy እን ዲሁ ክንዱን ክንዳ. ጋር እንና’ = PN ክርስቲያን ሃይማኖችና መርዓት ምዕራፍ 8ብ፮5 በአንዱ መጋረጃ ክፈፍ ላይ ከስማያዊ ሐር ክምስ ቀለ በቶችን ከመጋረጃው ጫፍ እንዲጋጠሙ አይረጉ ! አንዲ ሁም በሁለተኛው መጋረጃ ክፈፍ አምስ ቀለበቶች አንዲ መጋመጠሙ አድረጉ።",
    ),
    (29, 21, "አምሳ የወርቅ መያዣዎችን ሠሩ ፡ መጋረጃዎቹንም ኣርክ በርሳቸው በመያዣዎች አያያዙዋቸው ድንኳኑም አንድ ሆነ።"),
    (29, 22, "ከድንኳትም በላይ ዓሥራ አንድ መጋረጃዎችን ከፍ የል ጠኾር አደረጉ።"),
    (29, 23, "ለያንዳንዱም መጋረጃ ርዝመቱ ሠላስ ክንድ ለያንኝ ንዱም መጋረጃ ወርዱ እንዲሁ አራት ክንድ ሁኖ መጠናኛ ቸው ትክክል ነው።"),
    (29, 24, ") አምስቱንም መጋረጃች ርስ በርሳቸው ሰበቱንም መጋ ረጀት ርስ በርጳቸው ኣንድ አድርገው አጋጠሙዋቸው።"),
    (29, 25, "ክተጋጠሙትም መጋረጆች በአንደኛው መጋረጃ ዘር ፍ ሳይ ጾምጎ ቀለበቶችን ጸይረጉ።"),
    (29, 26, "ከተጋጠሙትም መጋረጃዎች በሁለተኛው eek ዘርፍ ላይ አምላ ቀለበቶችን አደረጉ።"),
    (29, 27, "ድንሕትም አንድ አንዲሆን ያጋጥሙት ዘንድ አምሳ የናስ መያዣዎችን ሠሩ።"),
    (29, 28, "| ለድንኳኑም መደረቢያ የለፉ የበግ ቈርቦት ኣዪረጉኑ ፡ ከዚያም በላይ ሴላ መደረቢያ ከአስቆጣ ቈርበት አደረጉ።"),
    (29, 29, "ስድንኳታም ከማይነቅዝ ቁንጨት የሚቆሙትን ኻን ‘ቋች አደረጉ ፣ ለክንዱም ሳንቃ ርዝመቱ አሥር ክኘጌድ፡ ወርዱ አንድ ክንድ ተኩል ነው።"),
    (29, 30, "ለያንዳንዱም ሳንቃ አንዱን ከሌላው ጋር የሚያያይዙ ሁለት ማጋጠሚያዎች ነበሩ ፡ ለድንኳዮም ስንቆች ሁሉ እንዲሁ አደረጉ • በደቡብም ወገን ሃያ ጳንቆችን አደረጉ።"),
    (
        29,
        31,
        "ለነያውም ጳንቆች አርበ የብር አግሮችን አደረጉ ' ለአ ንድ ላንቃ በሁለት ወገኑ ሁለት አግሮች በአንድ ወገኑም - | ሁለት እግሮች ነበሯት ' ከያንዳንዱም ሳንቃ በታች ሁለት ማጋጠሚያዎች ሁለት እግሮች ነበሩ።",
    ),
    (
        29,
        32,
        "ስድንኳኑ በሁለተኛው ወገን በሰሜን በኩል ሃያ ሳን | ቆችን አደረጉ» | ስያንዳንዱም. ሳንቃ አርበ የብር አግሮች ጸደሪጉ ፣ ከእ --[ -ያንዳንዱም ሳንቃ በታች ህት እግሮች እአደረጉጐ = ---- --- --- -- - -- ---- በምፅራብም በኩል በስተኋላ ከድንኳኑ ፊት ለፊት ሰበት ሳንቆችን አደረጉ።",
    ),
    (
        29,
        33,
        "ዳግመኛም ለማደሪያው ከሁለት ማዕዝን በስተኋላ ሁለት ሰንቋች አደረጉ = ትክክል .የሆኑ ክታ ችም አስክ ላይ እስከ አንደኛው ቀለ . በት ድረስ አንድ ጳንቃ ድርብ ነበረ ለሁለቱም ማዕዝን እንዲሁ አይደኑ።",
    ),
    (29, 34, ". ስምንት ስንቋችና ዓሥራ ስድስቱ የብር እግሮቻቸው RIS ላንቃ የታችኛ ሁስት ሁለት RE ነበሩ።"),
    (
        29,
        35,
        "ለድንኳኑ ነቶች ከማይነቅዝ giiaY መወርወርያ ዎችን. አደረጉ • nig r ክርስቲያን ሃይማኖትና ሥርዓት ራፍ ቛኗ « tei [ ' ;; በማይሪያውም በአንደኛው ወገን አምስት መወር -ወርያዎች በሁለተኛውም ወገን አምስት መወርወርያዎች | በምፅራቡም-ወገን አምስት መወርወርያዎችን አደረጉ።",
    ),
    (29, 36, "መካከለኛውንም መወርወርያ በሳንቆቹ መከከል ከዳር እስከ ዳር እንዲያልፍ አደረገው።"),
    (29, 37, "ስንቆቹንም ቀለበቶቹንም መወርወርያዎቹንም በወርቅ ለበጡቁዋቸው።"),
    (29, 38, '"መጋረጃውንም ከሰማያዊ ከሐምራዊ ከተፈተለ ቁይ ሐርና ከብጫ ሐር በርሱም ላይ በቫ ማኔነት አሠራር ኪሩ ቤልን ጸደረጉበት።'),
    (29, 39, "ስ ከማይነቅዝም ዕንጨት አራት ምስሰዎችን አደረጉላት ) ዘወርቅም ለበጡዋቸው ' ዙላበቻ ቸውም የወርቅ ነበሩ።"),
    (
        29,
        40,
        "ለነሱም አራት የብር ምፅፀማዶች (እግሮች) አደረጉ = የድንኳኑንም ደጃፍ የሚሽፍን ከሰማያዊና ከሐምራዊ ከቀይ ግምጃና ከተፈተለም ከጥሩ በፍታ በልዩ ሠራር የተሠራ መጋረጃን አደረጉ።",
    ),
    (
        29,
        41,
        "\" ' ለመጋረጃውም ከማይነቅዝ ፅንጨት አምስት ምስስ ዎች አደረጉላት በወርቅም ለበጡዋቸው ኵላቦቻቸውሙም Fe ናቸው አመስት ዩናስ እግሮችንም አደረጉላቸው ምዕራፍ መ፮ a በስልኤል ከማይነቋቓዝ ፅኘጨት (ግራር) ታቦትን ርዝ መቱ ሁለት ክንድ ተኩል ' ወርዱም ክንድ ክንድ ተኩል ' ቁመቱም አንድ ክንድ ተኩል ሠራ።",
    ),
    (29, 42, "በውስጥም በአፍአም በጥሩ ወርቅ ለበጣት ፡ በዙርያ ዋም የወርቅ አክሊል አደረገላት፡ በዙርያዋ ላሎ ቀለበ ቶች መቋሚያ ሊሆን ለክንፈርዊ የወርቅ ፈሰስ አወጣላት።"),
    (
        29,
        43,
        "አራት የወርቅ ቀለበቶችንም አደረገላት ፡ በራት አግ ሮቾም አኖራቸው ፡ በአንድ ወገን ሁለት ቀለበቶች በሌላ ውም ወገን ሁለት ቀለበቶች « ' መሎጊያዎቹንም ከማይነቅዝ\" ዕንጨት ሠርቶ. በወሮቕ ለበጣቸው።",
    ),
    (
        29,
        44,
        "ታቦቷንም በነሱ ለመሸከም በታቦቱ አጠገብ ባሉቱ አራት ቀለበቶች መሎጊያዎቹን አገበ = መክደኛውንም ከጽሩ ወርቅ UP ርዝመቱም ሁለት ሁለቱንም ኪሩቤል ከተመታ ወርቅ ሠራ ፡ በመክደኛ ውም ላይ በሁለት አደረጋቸው ' ከሥርየት መክደኛውም ጋር አንዱን ኪሩብ በአንድ ወገን ሁለተኛውን ኪ. ሩብ በሌ ላው ወገን አድርጎ በአንድ ላይ ሠራቸው = | ኪሩቤልም ከንፎቻቸውን ወጅ ላይ ዛርግትው የሥር የት መክደኛውን በክንፎቻቸው ሸፈኑ ፡ አርስ በርሳቹ ውም በመክደኛው ላይ ፊት ለፊት ይተያያሉ = ከማይነቅዝም ዕንጨት ርዝመቱ ሁለት ክንድ ወርዱም አንድ ክንድ ፡ ቁመቱም አንድ ክንድ ተኩል የሆነ ገበ ታን (ማእድን) ሠፉ።",
    ),
    (29, 45, "ሚል፡ 8 '፮ - ፲፪ = በጥሩ ወርቅም ለበጠው በዙርያውም የወርቅ አክ [| ሊል አደረገለት = ክንድ የዙል ወርዱም እንድ ከንድ ተዥል ነወ።"),
    (29, 46, "-- is ክርስቲያን ሃይማኖትና መርዓት #።"),
    (
        30,
        1,
        "በዙርያውም አንድ ጋት የሚያኽል የወርቅ ፈሰስ አዝረቦት በከንፈሩም ዙርያ አራት ቀለበቶችን ዜዪረገለት, ለክፈፉም መያዣዎችን ሠራለት = ለአክሊሉሱም አራት ቀለበት አዴረገለት ! ቁለ በቶቹንም አራቱ እግሮቹ በሉበት በአራቱ ማዕዝኖች አኖራቸው ገበታውንም ለመሸከም መሎጊያዎቹ አንሣኝ ሸከሙስበ ቸው ቀለበቶች በክፈፉ አጠገብ ነበሩ = | ገበታውን ይሸከሙበቸው ዘንድ መሎጊያዎቹንም ከማ ይነቅዝ ፀንኃት ሠርቶ በጥሩ ወርቅ ለበጣቸው።",
    ),
    (
        30,
        2,
        "ለማፍዕቫ ይሆኑ ዝንድ በገበታው ላይ የሚኖሩትን ዕቃዎች ወጧ ፉችን ጭልፋሩዎችን ጽዋዎትን መቅጃዎችን ከጥሩ ወርቅ ሠራቸው መቅረዘችንም ከተመታ ጥሩ ወርቅ አደረጋቸው መቅ ረዙንም ክአግሩና ከአገዳው ጋር ቦዋዎቹ ጐብጐፀቹና አበቦቹ ክከዘያው ተሠሩ።",
    ),
    (30, 3, ") ለመብራቱም መቅረዝ በስተጐኑ ሰበት ቅርንጫፎች ወጡስለት ፡ ሦስቱ ቅርንጫፎች በአንድ ወገን ምክኾም ቅር ንጫፎች በአንድ ወገን ወጡ።"),
    (
        30,
        4,
        "በአንደኛው ቅርንጫፍ ጐጕብኑ ቡንና አበባውን ሦስትም የለውዝ አበበ የሚመስሉትን ፀዋዎች በሁለተኛው ቋር . ንጫፍ ጐኮብኑቡ ነና አበባውን አንዲሁም ከመቅረዙ ለሚ ወጡ ለሰበቱ ቅርንጫፎች አዴረገ።",
    ),
    (30, 5, "7 | በመቅረዙም ጐብኑጉቦቹንና አበቦቹን አራትም የለ ውዝ አበበ የሚመስሉትን ጽዋዎች ክይረገ።"),
    (30, 6, "ጐኾብኑጉቦችና ቅርንጫፎቹም ከርሱ ጋር አንድ ነበሩ ሁሉም አንድ ሁኖ ክተቀረፀ በጥሩ ወርቋ ተሠርቶ ነበር።"),
    (30, 7, "ሰበቱንም መብራቶች ስዋዎችንም መኰስተሪያዎቹንም የዙክታሪ ማድረጊያዎቹንም ከጥሩ ወርቅ ሠራ መቅረዙንም ዕቃውንም ሁሉ ከአንድ መክሊት ጥፍ ወርቅ አይሪረጌ።"),
    (30, 8, "ከማይነቅዝም ዕንጨት ርዝመቱ አንጅ ክንድ ስፋቱ አንድ ክንድ አራት ማዕዝን የሆነ የዕጣን መሠውያን ሠራ።"),
    (30, 9, "ከፍታውም ሁላት ክንድ ነበረ ፡-ቀገዶቐመ ከሱ ጋር የተሠሩ ነበሩ።"),
    (30, 10, "ላይኛውንና የ ግድግዳውን ዙርያ ቀንዶቹንም በወርቅ ለበወው።"),
    (
        30,
        11,
        "በሆርያውም የወርቁ ክፈፍ ኣአዴረገለት ፡ ከክፈፉም በታች ሁለት የወርቅ ቀለበቶች ሠርቷ በሁለት ጐኑ አደ ረጋቸው ፡ አሱን ያነውበቸው ዝንድ EE ስራፍ ነበሩ = መሎጊያዎቹም ዘማይነቅዝ ዕንጨት ሠርቶ ብወፎቅ ለበጣቸው።",
    ),
    (30, 12, "የሚቀቡት ንም ቅበት ከዘይት ኣደረገ, ጥሩውንም የጣፋጭ ሽቱ ፅጣን በቀማሚ ብልሃት የተቀመመ እጸዪረን።"),
    (
        30,
        13,
        'ርዝመቱ አምስት ክንድ፡ ወርዱም አምስት ክንድ ለሚቃጠል መሥዋዕት የሚሆን ከማይነቅዝ ዕንጨት ሠመራ ከፍታውም ምስት ክንድ ሆያ አራት ማsዝን ነበር = ክርስቲያን ሃይማኖትና ሥርዓት " መጨ ሴቶች አንጻር አኖረው።',
    ),
    (
        30,
        14,
        "ራፍ ዳሯ = h te እግሮቹንም በአራት ማፅዝኑ አደረገ ፡ ማቆrያዎቹም | ከር ጋር አብረው የተሠሩ ነበሩ = ቀንዶችንም በአራት ማፅዝኑ አደረገላት ፡ ቀንዶቹም ) ከርሱ ጋር በአንድነት የተሠሩ ናቸው ፡ በናስም ለበጠው።",
    ),
    (30, 15, "የመሠወውያዎቹንም ዕቃዎች ሁሉ! ምንቸቶቹን መጫ ሪያዎቹን ፡ ድስቶቹን ሜንወቹንና የአለት ማንደጃዎቹን | ሁሉ ከናስ አረገ።"),
    (30, 16, "iy አንደ ዓሣ መረብ ሁኖ የተሠራም ለመሠወያው መጥ ' በቫ.የናስ መክታ አደረገ።"),
    (30, 17, "nh ለመጥበቫውም አራት የናስ ቀለበቶችን በአራት A ዝኑ አደረገለት።"),
    (30, 18, "መከታውንም አስከ መሠውያየው አዙሴታ Sደርስh ዘን ድ ከመሠውያው ቤት በታች አኖረው።"),
    (30, 19, "ለመሎጊያዎቹም ሥፍራ ይሆኑት ዛንድ ለአራቱ ማፅዝ - ወች አራት የናስ ቀለበቶችን ሠራ = - መሎጊያዎቹን ከማይነቅዝ ዕንጨት ሠርቶ በናስ ለበ ጣቸው።"),
    (30, 20, "መሎጊያዎቹንም አሱን ይሸክሙበቸው ዘንድ በመሠውያው ጐን ላይ በሉት ተለበቶች መከተ. አግበ ) ከሳን ቆቐም ሠርቶ ክፍት አድረገው።"),
    (
        30,
        21,
        "መቅለዱንና እግር ዛቍነውን ከናስ ሠርቶ (ሌዋውያን) በሚታጠቡበት በደብተራ ኦሪት ደጃፍ ሊጻልዩ በሚ ለደብተራ አሪት በካተደቡብ በቀኝ በኩል አደባባይ ሠራ '፡ የአደበበዩም መጋረጃ ርዝመቱ መቶ ክንድ የሆነ ፣ ዕፅፍ ሁኖ ከተፈተለ ብሟ ሐር የተሠራ ነው ሃያ የብር ምሰስዎችንና ሃያ የብርት ምዕማዶችን ሠራ ለምሰስዎቹም ዙላቦቻቸውንና ዘንጎቻቸውን ከብር አደረገ።",
    ),
    (30, 22, "በስተ ሰሜንም መቶ ክንድ ርዝመት ያለው መጋ ረጃን’ አደረገ።"),
    (30, 23, "ሃያ የብር ምስሰዎችንና የኛስ እግሮችንም ሠራ! ለም ስስዎቹም የብር ኵላቦችንና ዘንጎችን አደረገ።"),
    (
        30,
        24,
        "በስተ ምፅራብም ርዝመቱ ጸምዛ ክንድ ያለውን መጋ ረጃ ሠራ፡ ዓሥር ምሰሶዎቹ ከብር ፡ ዓሥር እግሮቹ ክናስ የተሠሩ ነበሩ = . --- የምስስዎቹም- ዙላበችና-ዛ በስተ ምሥራቅም ርዝመቱ አምላ ክንድ ያለውን ረጃ ሠራ ፡ ክብር የ ተሠሩ ምሰሶዎቹ ዓሥር ከናስ የቱ ሠሩ እግሮቹም ዓሥር ነበሩ።",
    ),
    (
        30,
        25,
        "በጸንዱም ወገን ርዝመቱ ዓሥራ አምስት ክንድ ምስ ስዎቹ ሦስት ም ዕማዶቹም EN ነበሩ = ፪ WE {gs በሁለተኛውም ወንኝ ርዝመቱ ዓሥራ አምስት ክንድ ያለውን መጋረጃ አዪረገ ፡ ምዕስዎቹም ሦስት የም ስስዎቹ ምዕማድም ምስት ነበሩ ፡ በአዶበበዬዩ ዙርያ ZN መጋ ረጃ ሁሉ. ከጥፍ በፍታ የተሠራ ነው።",
    ),
    (30, 26, "የአደባበዩም ምስሶች ሁሉና ክበስቻቸው በብር የተለ. በጡ ነበሩ ምዕማዶቻቸውም ከናስ የተሠሩ ናቸው።"),
    (30, 27, "3ጓግች የብር -ሃነበሩ።"),
    (
        30,
        28,
        "--- -- - ክርስቲያን ሃይማኖትና መርዓት Ord ኃያ ክንድ የሆነ የክዴበበዩም ደጅ መጋረጃ ከሰማያ ወና ከሐምራዊ ሐር፡ ከቀይ ግምጃ ክጥሩ በፍታም በልዩ ጥልፍ አሠራር የተሠራ ንስር = ርዝመቱ አምክት ክንድ ! ቁመቱም እንደ አደበበዩ መጋረጃ አምስት ክንድ ነበር = ዛፀ6፡ 68 ፩-፮።",
    ),
    (30, 29, "አራት ምስስዎቹ ከብር አራት ምዕማድቹም ክናኽ የተ ሠፉ ነበሩ ፡ በደብተራ ኦሪት ዙርያ ያሉ ካስማዎች ሁሉ .የ5ስ ነበሩ።"),
    (30, 30, "መሴ ከአግዚአብሔር አንደ ታዛዘው ስሌዋውያን ማነ ልግያ አንዲሆናቸው በክህኑ በአሮን ልጅ ህይታምር የተ ቂጠረው የደብተራ አሪት ዕቃ ድምር ይህ ነው።"),
    (
        30,
        31,
        "ዘሌ ፳ 18 ከነገደ ይሁዳ ወገን የሆነ የሑር የልጅ ልጅ የኡደ'ይጅ ብስልኤል እግዚአብሔር ለሙሴ እንዳዘዘው ሁሎን ሠራፉ፥ በሽማኔነት በግብረ መርፌና በጥልፍ ሥራ የጥበብ አ ለቃ የሆነ የዳን ነገድ ወገን የአክሴምክ ልጅ ኤኳሕያብም በሰማያዊ በሐምራዊ ፅፅፍ ሁኖ በተፈተለ ቀይ ግምጃና በብጫ ሐር ይሠራ ዘንድ ከር ጋር ነበር።",
    ),
    (30, 32, "የደብተራ አሪት ሥራ የተሠራበት የመበው ወርቅ ሠሉ በቤተ እግዚጾብሔሑር አዋቂ ሚዛን ሃያ ዘጠኝ መክ ሊት ስባት መቶ ሠላሳ ወቁት ሆ፥።"),
    (
        30,
        33,
        "ዘፀ, ፳፮ ፲፱ - ፳8 = ከከተማው ጾቆጣጥረው ያ መጡት ክስፎኤል መበ አድ ርገው የቀረቡት ብርም በመቅደሱ ሰቅል ሚዛን መቶ መክ 'ሊት ፡ ሹሕ ሰበት መቶ ኣምስት ወቁት ሆነ።",
    ),
    (30, 34, "በየራጓቸው ያወጡትም ገንዘብ አንድ ኳጸንድ. ወደት ነው ይኽውም አንድ ድሪም አቀመት የ ስቅል ግማሽ ነው።"),
    (30, 35, "ይህንም ኘኘዘብ ለመስጠት ሲዴቂመጠር የሄደው ሰው ከ ሃያ ዓመት ደምሮ ከዚያም በላይ የሆነው ስዛ አልፍ ከቻ ከኮት ሹሕ ጸምስት መዯ ክምላሓ ነበር።"),
    (30, 36, "ይኸውም መዯቶው የብር መክሊት ጸዪብተራ ጾሪት መሰስዎች ክዕስ ለመጋረጃው ምዕሰስዎችም አግር ተሠ ራሳቸው።"),
    (30, 37, ". ' ይህም መቶው መክሊት ለመቶው ክባስች ለያንቋዳን . ዲቱ መክሊት በያ ንዳንዲቱ „ራክ ላይ ነው።"),
    (
        30,
        38,
        "| b ይሀንም ሽሕ ክሰበት መቶ ስበ አምስቱን ወቁ ለዙ ርያ ቅጥሩ አዕማድ ክበስ አድርገው ሠሩት = ለእግዚአብሔር መበ ሆና የገባው ብርቱም አራት መቶ- ወቄት ሁለት ሺሕ ክራት መቶ በቅል ነው።",
    ),
    (31, 1, "----- -- -- | ሙሴም ከዚህ ብረት ለዪብተፉ ኦረት ‘ደጃፍ መድረክ | -|. መሥዋዕት የሚሠዋበትን መሠውያንን አደረገ።"),
    (31, 2, "መሥዋዕቱ የሚጠወበስበት መጥበስትን ፡ የምሥወፁን ሥራ ሁሉ ሠራበት።"),
    (31, 3, 'በዙርያው ላለውም ቅጥር አዕማድ ፡ ለኩርያ ቅጥሩም " በር መድረክ ፡ ለደብተራ ኦሪትም ክስማ ACE ላለው. . ሽማ ቅጥርም ክከስማ ሠራለት።'),
    (31, 4, "ስመበ ከንበው ወርቅ የተረፈው ወርቅ ግን በእግዚአ ብሔር ፊት በሚሠሩበት ገንዘብ ሴላ ዕቃ ተሠራበት።"),
    (
        31,
        5,
        "ክርስቲያን ሃይማኖትና ሥርዓት ፍ ወ፱ = iy, ፣'፡ ከቋማያዊ ከሐምራዊና ከቀይ ሐር ከብጫ ሐርም በመቅደስ ለማገልገል ልብስ ቶሠራ = | ) ኣግዚጸብሔር ሙሌን እክንዳዘዘው-ም የተቁድበውን | ልብስ ለአሮን ሠሩለት = ፡ ዜድ ንም በወርቁ በበ(ማያፍ ይር, በቁምራዊ -ሐር ራፍ ሁና ከተፍተለ ከብጫ ሐርና ከቀድ ግምጃ ዜይረን።",
    ),
    (
        31,
        6,
        "- ወርቁንም እንደ ቅጠል አሳስተው እየiጠቁ ከሰማ [ ያፍ ከሐምራዊ ከቀይና ከብጫ ሐር ጋር እየተሸረበ አን | ዳፈቱል አደረጉት = በሁለቱ .‘ሜንቃዎቹ የሚወርድ ልብሰ መችከፍትን i ውሩ! ከአራቱ ሣብርም በሁላት ወገኖቹ የሚገኗ'ድ ሁለት ቁሚሰቹ፣ ሠፋ።",
    ),
    (
        31,
        7,
        "ኢሳ፡ ፲8 ፩፡ ራፅ፡ ዮብ ቛ ፲፫ = እግዚጾብሔር ሙሴን እንዳዘዘው አፉን በወርቀ በሐ ምራዊ በሰማያዊ በብጫና በቀይ ግምጃ አንደሠሩ የልብሰ መትከፉን መታጠቂያ አድርገው ሠፋፉት = oy eee (6ንሑ) ደንጊያዎችንም ሠርተው ከወርቅ ጋር አስማምተው እንደ ማሣተም ቅርጽ አድርገው የኣስ ) ራሌል ልጆች ስም ቀረፁበቸው = ኢያ, 8 £።",
    ),
    (
        31,
        8,
        "ለእስራኤል ልጆች የመታሰቢያ ድንጋዮች ይሆኑ ዘንድ አግዚአብሔር ሙሴን እንዳዘዘው ጸድርገው ፀንቁቆ -ቑን በኤፉዱ ጫንቃ ቀሚፀች ላይ . አኖሩዋቸው = - የደረቱን ኪስ እንደ ኤፉድ አሠራር ብልሃት ሥራ በወርቅ በሰማያዊ በሐምራዊ በቀድና በብጫ ሐር ሠሩት ፡ ምፅዙንና ድርብም አደረጉት።",
    ),
    (
        31,
        9,
        "ሕዝ፡ ፳፳ ፲፫ • የደረቱን ኪስ (ልብሰ ሎግዮ) ድርብ ሁኖ ርዝመቱ ክ '\" ንድ ‘ወርዱም ክንድ -ነበረ፡ በርሱም ጸራት ‘ተራ የ አክ ናቀ“ ፈርጥ አደረጉበት = ) አንደኛው ተራ ሰርድዮን ፡ ጸዝዮን መረግድ = ሁለተኛው ተራ እንደ ፍም መልክ ያለ ፅንቍ ሰንፔር ኢያሰሏጺድ = ሥስተኛው ተራ በለግርዮን (ያክንት) ኬልቄድን አሜ ቴስዉጢናኖስ = አራተኛው ተራ ወርቅማ ዕንቍ ቢረሌ ምም ሲሆኑ ሕ \" ሊህ'ሁሱሉ በወርቅ ፈርጥ የተያዙ ናቸው።",
    ),
    (31, 10, "አነዚህም ዕንቆች በዓሥራ ሁለቱ የአስራኤል የተቀረፁ ናቸው።"),
    (
        31,
        11,
        "ለደረቱም ኪስ የተጐነጐኑትን ድሪዎች እንደ ገመድ አድርገወ፡ ከጥፍ. ወርቀ ሠሩለት = ሁለት የወርቅ ፈርጦችን ሁለት የወርቅ ቀለበቶችንም [ ሠርተው እያን ሁለት ቀለበቶች በሁለት የድረት ኪስ ጫፎች አደረጉዋቸው።",
    ),
    (31, 12, "ሁለቱንም የተጐነጐትትን የወርቁ ድሪዎች በደ ረቱ ኪስ ወገኖች ወዳሉት ወድ ሁለቱ ቀለበቶች ' አደረጉ (አገቡ)።"),
    (31, 13, "ሁለቱንም የድሪ ጫፎች በሁለቱ ፈርጦች ውስጥ ጸግብ ተው በኤፉድ ጫንቃዎች ላይ ፊት ለፊት አይረጉዋቸው።"),
    (
        31,
        14,
        "ሁለቱንም የወርቅ ቀለበቶች ሠርተው በኤፉዱ ፊት ክርስቲያን ሃይማኖትና ሥርዓት Ord ዕርፍ aB ሐፊት በአው በደረቱ ኬስ በሁቱ ጫፎቹ ሓይ አደረ ጐዋቸው = የደረቱን ኪስ በብልሃት ከተጠለፈው ከኤፉድ ‘ቋድ በላይ እንዲሆን ፡ ከኤፉዱም እንዳይለይ የደረቱን ስ. ከቀለበቶቹ ጋር ወደ ኤፉዱ ቀለበቶች በሰማያዊ ፈትል አያያዙት አግዚአብሔር ሙሌን እንዳዘህው = ኤፉዱን ቀሚስ ሁለንኛናው ብሸሽማኔ ሥራ አሠራር በሰማያዊ ሐር ሠሩት ፡ እንዳይቁቀይዪድም አንይ ጥሩር የቱ ሠራ ጥልፍ በአንንትጌው ዙርያ ነበር = በቀሚሱም ታችኛው ዘርፍ ከሰማያዊ ከሐምራዊ ከቀይ ግምጃና ከብጫ ሐር አንደ ሮማን ፍሬዎች በዙ ርያው ላይ አደረጉ።",
    ),
    (31, 15, "| ክጥሩ ወርቅም ጸናጽሎችን (ቃጭሎች) ሠርተው ቃጭሎቹን በቀሚሱ ኮርያ ዘርፍ ላይ በሮማናቹ መከከል እድረጉዊቸው።"),
    (31, 16, "| አግዚአብሔር ሙሌን እንዳዛዛው የሚያገለግሉበትን አንድ ጸናጽል አንድ ሮማን! አንድ ሮማን አንድ ጸና ጽል አከታትለው በሮማናኖቹ ውስጥ እይረጉ።"),
    (31, 17, "ለአሮንና ልጆቹ አንደ ሸማኔ አሠራር ከነጭ ሐር መጠምጠሚያን ከነጭ ሐርም ቆብን ከነጭ ዩየተልበ አግር ስናፊዶን ሠሩላቸው።"),
    (31, 18, "እግዚአብሔር ሙሴን . አንዳዛዛው ከነጭ ሐር ፡ ከስ ማያዊ ከሐምራዊ ከቀይ ግምጃ በጥሩ አሠራር የ ተሠ መታጠቁያዎችን ሠሩ።"),
    (32, 1, "ከጥሩ ወርቋ የተለየ (የተቀደሰ) አሳክተው ሠርተው በላዩ ላይ አንደ ማሣተም ቁርፅ ለአግዘ አብሔር ቅዱስ መ በል ይንበል የሚል ጸፉበት።"),
    (32, 2, "ክፀ፣ ጄሯቿ ማዩ = አግዚአብሔር ሙሴን ክንዳዛዛክው በመጠምጠሚያው ላይ ያንጠለጥሉት ዘንድ ሰማያዊ ሐር ክሠሩበት።"),
    (32, 3, "የደብተራ ኦሪት ሥራ ሁሉ ተፈጸመ ፡ የአስራኤል ልጆችም አግዚአብሔር ስሙሌ ያዛዘውን ሁሉ ሠርተው ፈይ።"),
    (32, 4, ") ድንኳጨኒቱንም. ዕቃዎቻን. ሁሉ መደረቢያዎቿን ም ሰስ ቿን መያተዎቹን መወርወሪያዎቹን የምሰስዎቹን እግ ሮች ሁሉ ወደ ሙሌ አመጡ።"),
    (32, 5, "ዘፀ! ፪ጀ 3 = | ከአውራ በኝ ቈርበት የተሠሯ መደረቢ:ያዎች ክአስቁጣ - ቈርበት የተሠሩ ማአስ መጸጺቶች የሚሸፍነውንም መጋ ረጃ የምስክሩንም፡ ታቦት።"),
    (
        32,
        6,
        "መሰጊያዎቿን የሥርየት መክደኛውን ገበታውን ከነ ዕቃዎቹ ሁሉ የሚያቀርቡትንም ዓብስት = የእፎውን ‘መቁረኽ SETS RY ዕቃ ዎቋን ሁሉ = EF የመብራቱን ዘይት የወርቅ. PRY የሚቀቡ iy ንም ቅብዓ ቀዱስ የሚያጥሦኑትን ጥሩ. ዕጣን = . ) የደብተራ አሪትን ደጃፍ መጋረጃ የናሱን መሠውያ ' የናሱን መክታ (መጥበሻ) መሎጊያዎቹ ንና ዕቃውን ሁሉ።",
    ),
    (32, 7, "መታጠቪያን ከነመቀመጫው የአይበበዙን መጋረጃ ምሰ Ort ራፍ 9።"),
    (32, 8, "EYE ዕዎቹንና እግርቻቸውን = iy የ ጸዶበበዩን ደጃፍ መጋረጃ ለበን ለሎቶቹ ት} አው ses ቹ ን ዘስማዎቹን ለደብተራ ኦሪት የሚሆኑ ዕቃዎችን ሁሉ።"),
    (
        32,
        9,
        'በመቅደሱ ውስጥ ለማገልገል የተቀደሱትን የክሀኑ የአሮንን ልብዕች በክህነት ሊያገለግሉት የልጆቹንም ልብ ለች የቀሩትንም ለደብተራ ኦሪት ሥራ የሚሆታ ልብለችን ሴላወ"ን የሚሸፍኑበቸውንም ፡ ወደ ሙሴ አመጡ።',
    ),
    (
        32,
        10,
        "' ኣግዛክአብሔር ሙሴን እንዳዘዘው ሁሉ የአስፍአ፡ል ልጆች ሥራውን ሁሉ እንዲሁ አደረጉ - « ሙሴም የተሠራውን ሁሉ አየ ፡ እነሆም እግዚአብሔር አንዳዛዘዛው እንዱሁ አንደተይረገ አይቶ በረካቸው።",
    ),
    (32, 11, "እግዚጸብሔርም ሙሌን አንዲህ ብሎ ተናገረው ፡ ከመ ጀመሪያው መር በፊተኛው ቋን የመገናኛውን ድንኳን ትተክላለህ።"),
    (32, 12, "ዛፀ፡ ፲፪ ፪፡ ግብ፡ ሐዋ፡ ፮ 38 gk = በርሷም ውስጥ የምስክሩን ታቦት ታኖራለህ ታቦቱ ንም በመጋረጃ ትጋርዳለህ።"),
    (
        32,
        13,
        "ገበታውንም አግብተህ በርሱ ላይ የሚኖረውን ዕቃ ታሰናዳለህ id RES RY NE ላለህ = በም ስክሩም ታቦት ፊት የወርቅ ማዕጠንትን ታኖራ ለሀ፡ በደብተራ “አሪትም ደጃፍ ፊት መጋረጃውን ትጋ ርዳSAY ' ለሚቃጠል መሥዋዕት የሚሆነውንም መሠውያ በመ ገናኛው ድንኳን በማደሪያው ደጅ ፊት ታኖረዋለህ ፡ የመ ታጠቢያውንም ሰን በመገናኛው ድንኳንና በመሠውያው መክከል አኑረህ ውኃ ትጨምርበታለህ።",
    ),
    (32, 14, "vy 5 በዙርያውም አደባባዩን ትተክላለህ ፡ የአደባባዩንም (ወትተ ክል) ፎጃፍ መጋረጃ ትዛረጋለህ።"),
    (32, 15, "የሚቀቡትን ቅብዐ ቁዱስ ወስዶህ ድንኳን በውስጪ የለውንም ሁሉ ቅበ ፡ እርሱንም ዕቃዎቹንም ሁሉ ትቀድ ዘዋለህ\"፡ “ቅዱክም 'ይሆናል።"),
    (32, 16, "ዘፀ ብ ፳፫-- ጽቕ።"),
    (
        32,
        17,
        '" ለሚቃጠል መሥዋዕት የሚሆነውንም መሠውያና ዕ# ውንም ሁሉ ትቁበዋለህሀ፡ መሠውያውንም ትቀድሰዋለህ መሠውያውም ቅዱስ ቅዱሳን ይሆናል ፡. የመታጠቢያውን | 3 መቀመጫውንም ቀብተህ ቀድሰው = -ዘ0፡ ፳፱- ዘ፮=- - -- አሮጎንና ልጆቹን ወደ መገናኛው ድንኳን PER በው አጠባቸው።',
    ),
